document.addEventListener('DOMContentLoaded',function(){var els=document.querySelectorAll('.sx-texto');if(!('IntersectionObserver' in window)){els.forEach(function(e){e.classList.add('tx-on')});return}var io=new IntersectionObserver(function(es){es.forEach(function(x){if(x.isIntersecting){x.target.classList.add('tx-on');io.unobserve(x.target)}})},{threshold:.5});els.forEach(function(e){io.observe(e)})});